export const getReportReviewUrl = (reviewId: string,) => {




  return `/v1/reviews/${reviewId}/reports`
}

/**
 * Motivo `SPAM`, `OFFENSIVE`, `FALSE_INFO`, `PERSONAL_DATA` ou `OTHER`, com texto opcional. Uma denúncia por pessoa e avaliação (409 `REVIEW_ALREADY_REPORTED`); a própria não (403 `REVIEW_REPORT_OWN`). A avaliação continua publicada até a moderação do Super.
 * @summary Denunciar uma avaliação (RN-REVIEW-04)
 */
export const reportReview = async (reviewId: string,
    reportReviewInput: ReportReviewInput, options?: Parameters<typeof customFetch>[1]): Promise<void> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<void>(getReportReviewUrl(reviewId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(reportReviewInput)
  }
);}





export const getReportReviewMutationKey = () => ['reportReview'] as const;

